from typing import Optional

import torch

from sglang.srt.debug_utils.comparator.dims_spec.types import DimSpec

# Attribute used to carry dimension names on a tensor view. We intentionally do
# NOT use PyTorch's native named-tensor mechanism (``refine_names`` / ``.names``)
# because named tensors do not support common operations such as ``reshape`` or
# einops ``rearrange`` without first stripping the names. Instead we stash the
# names in a plain Python attribute on a tensor view, which is transparent to
# every standard tensor operation.
_DIM_NAMES_ATTR = "_dim_names"


def find_dim_index(dim_specs: list[DimSpec], name: str) -> Optional[int]:
    """Find index by name. Accepts both ``*``-form and ``___``-form for fused dims."""
    for i, spec in enumerate(dim_specs):
        if spec.name == name or spec.sanitized_name == name:
            return i
    return None


def get_dim_names(tensor: torch.Tensor) -> tuple[Optional[str], ...]:
    """Return the dimension names attached to ``tensor``.

    Reads the custom ``_dim_names`` attribute set by :func:`apply_dim_names`.
    When no names have been attached, returns ``(None,) * tensor.ndim``.
    """
    names = getattr(tensor, _DIM_NAMES_ATTR, None)
    if names is None:
        return (None,) * tensor.ndim
    return tuple(names)


def without_dim_names(tensor: torch.Tensor) -> torch.Tensor:
    """Return a new tensor view of ``tensor`` with no attached dimension names.

    The returned view shares storage with ``tensor`` (data is preserved) but is a
    distinct Python object, so it does not carry the ``_dim_names`` attribute and
    :func:`get_dim_names` on it returns a tuple of ``None`` values.
    """
    return tensor.view_as(tensor)


def resolve_dim_by_name(tensor: torch.Tensor, name: str) -> int:
    names: tuple[Optional[str], ...] = get_dim_names(tensor)
    if all(n is None for n in names):
        raise ValueError(f"Tensor has no names, cannot resolve {name!r}")

    try:
        return list(names).index(name)
    except ValueError:
        raise ValueError(f"Dim name {name!r} not in tensor names {names}")


def apply_dim_names(tensor: torch.Tensor, dim_names: list[str]) -> torch.Tensor:
    if tensor.ndim != len(dim_names):
        raise ValueError(
            f"dims metadata mismatch: tensor has {tensor.ndim} dims (shape {list(tensor.shape)}) "
            f"but dims string specifies {len(dim_names)} names {dim_names}. "
            f"Please fix the dims string in the dumper.dump() call to match the actual tensor shape."
        )
    named: torch.Tensor = tensor.view_as(tensor)
    setattr(named, _DIM_NAMES_ATTR, tuple(dim_names))
    return named
